export function roofCall(g) {
  return roof(g, ROOF_FOOTPRINT, "shop", {
    y: 17, pitch: "half", maxHeight: 3, overhang: 1, material: "dark-slate", gable: "bamboo_mosaic",
    ridge: "crest", dormers: { count: 0 },
    chimneys: [{ at: [1, 12], size: 1, material: "bricks" }, { at: [1, 21], size: 1, material: "bricks" }],
    keep: [{ from: [0, 16, 3], to: [15, 21, 7] }],
  });
}

