// Helpers only ADD into air; a part that calls them must not overwrite the shell.
import { B, DIRS, roof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

// ---- SITE (plan.md, inclusive ranges) ----------------------------------------------------------------------------
