/** Street lamp at (0, *, 1): a polished_blackstone_wall post at y1..3 and a standing lantern at y4. */
export function streetLamp(g) {
  for (let y = 1; y <= 3; y++) g.set(0, y, 1, POLISHED_BLACKSTONE_WALL, { up: "true" });
